#include <stdio.h>
/* ex01：四种 I/O 控制方式下 CPU 的介入代价
 * 场景：从慢速设备读 4KB，设备每传 1 字节耗 0.5ms，整个传输窗口 2048ms。
 *   程序查询：CPU 死循环查状态位（忙等），整个窗口都被占住
 *   中断驱动：每 2 字节中断一次（16 位设备），CPU 只在中断处理时被占用
 *   DMA：整块传完只中断 1 次
 *   通道：通道程序自己跑，I/O 结束才中断 1 次，还能同时管多台设备
 * 输出：介入次数、CPU 时间、CPU 占用率、传输期间能否并行做别的事。*/
int main(void) {
    int    bytes   = 4096;                 /* 一次传输 4KB */
    double poll_ns = 200.0;                /* 一次轮询的 CPU 时间(ns) */
    double int_ns  = 1200.0;               /* 一次中断处理的 CPU 时间(ns) */
    double byte_ms = 0.5;                  /* 设备每传 1 字节耗时(ms) */
    double window  = bytes * byte_ms;      /* 整个传输窗口(ms) = 2048 */

    long poll_cnt = bytes;                 /* 每字节轮询一次 */
    long int_cnt  = bytes / 2;             /* 每 2 字节中断一次 */
    long dma_cnt  = 1;                     /* 整块结束中断一次 */
    long ch_cnt   = 1;                     /* 通道结束中断一次 */

    double poll_ms = poll_cnt * poll_ns / 1e6;
    double int_ms  = int_cnt  * int_ns  / 1e6;
    double dma_ms  = dma_cnt  * int_ns  / 1e6;
    double ch_ms   = ch_cnt   * int_ns  / 1e6;

    printf("传输 %d 字节，设备 %.1fms/字节 -> 传输窗口 %.0fms\n", bytes, byte_ms, window);
    printf("轮询 %.0fns/次，中断处理 %.0fns/次\n", poll_ns, int_ns);
    printf("----------------------------------------------------------------------------------\n");
    printf("%-10s %-12s %-14s %-11s %s\n", "方式", "CPU介入次数", "CPU时间(ms)", "CPU占用率", "传输期间CPU可否并行");
    /* 程序查询是忙等：有效计算只花 0.8ms，却把 2048ms 全占了 —— 这是它最致命的地方 */
    printf("%-10s %-12ld %-14.3f %10.4f%% %s\n", "程序查询", poll_cnt, poll_ms, 100.0, "不能（死循环查状态位）");
    printf("%-10s %-12ld %-14.3f %10.4f%% %s\n", "中断驱动", int_cnt, int_ms, 100.0 * int_ms / window, "能");
    printf("%-10s %-12ld %-14.3f %10.4f%% %s\n", "DMA", dma_cnt, dma_ms, 100.0 * dma_ms / window, "能（只在结束时被打扰）");
    printf("%-10s %-12ld %-14.3f %10.4f%% %s\n", "通道", ch_cnt, ch_ms, 100.0 * ch_ms / window, "能（还能同时管多台设备）");
    printf("----------------------------------------------------------------------------------\n");
    printf("关键读法：不要只看 CPU 时间这一列。程序查询的有效计算只有 %.3fms，\n", poll_ms);
    printf("          但它把 CPU 钉在轮询上 %.0fms —— 占用率按「忙等窗口」算就是 100%%。\n", window);
    printf("结论：DMA 把「每字节一次」变成「每块一次」，是 I/O 效率的第一次飞跃；\n");
    printf("      通道进一步让 CPU 只下命令，连块搬运都不管。\n");
    return 0;
}
